"""Literal design-golden and pure negative evidence. No native or Project I/O."""
from dataclasses import replace
from hashlib import sha256
import math
import struct
import threading

import pytest

from ai_video_production import task048_meter_protocol as p

# Independent design 99913B95... literal bytes; not generated by the implementation.
GOLDEN = {
    "BOOTSTRAP": (186, "0b7ec9a406d8f037817b15cb09727dce97fa986d0746411a828af2fb7a98c982",
        ""),
    "WINDOW": (197, "d0a487a835800ee4e46a5e12151a9fbb7b71f7cb15031035e23782a1882a9a21",
        ""),
    "INVALIDATE": (120, "54faa59d734159f75f1873922e6c0087d24a0fc93e748a640b92a606a594b165",
        "7400000042564d31010004000300000000000000000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f0000000000004000800000000000000600000000000040008000000000000001000000000000400080000000000000080000000000004000800000000000000904010000"),
    "CLOSE": (72, "5929b9d7c39d7f37c7aa39e3e12d54ab70989fa31681ced0902fa657cf2ddca3",
        "4400000042564d31010005000400000000000000000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f0000000000004000800000000000000601000000"),
    "RESULT_READY": (208, "b19f2a87777de9aa22eda6f40d6384bc3ac1908694fb705fe977e8a385969b85",
        ""),
    "RESULT_STATUS": (112, "8ad4e11ea9d42886198dcb5addf8ecddb27552f8ae38fa1d1998a9f7cd02a05e",
        "6c00000042564d31010003000300000000000000000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f02080400030000000000000054faa59d734159f75f1873922e6c0087d24a0fc93e748a640b92a606a594b16500000000000040008000000000000006"),
    "RESULT_PROJECTION": (3822, "16295d65b8b56d97ce55f15f39de0d7c0764f4b20661463d8c2a0c8b33672a8a",
        ""),
}

def message(name="WINDOW"):
    return p.decode_message(bytes.fromhex(GOLDEN[name][2]))


def window():
    return message().body


def uid(n):
    return f"00000000-0000-4000-8000-{n:012x}"


def wire(body, sequence=2):
    return p.encode_message(body, nonce=bytes(range(32)), sequence=sequence)


def changed(raw, offset, value):
    out = bytearray(raw)
    out[offset:offset+len(value)] = value
    return bytes(out)


@pytest.mark.parametrize("name", GOLDEN)
def test_seven_literal_design_vectors(name):
    length, digest, literal = GOLDEN[name]
    data = bytes.fromhex(literal)
    assert len(data) == length
    assert sha256(data).hexdigest() == digest
    result = p.decode_message(data)
    assert p.encode_message(result.body, nonce=result.nonce, sequence=result.sequence) == data
    assert result.sha256.hex() == digest


@pytest.mark.parametrize("bad", [None, "", bytearray(b"a"), memoryview(b"a"), 1, True, {}, []])
def test_exact_bytes_only(bad):
    with pytest.raises(p.ProtocolError):
        p.decode_message(bad)


@pytest.mark.parametrize("name", GOLDEN)
@pytest.mark.parametrize("mode", ["short", "extra", "size_minus", "size_plus", "magic", "version", "type", "nonce", "sequence"])
def test_malformed_frame_rejected(name, mode):
    raw = bytes.fromhex(GOLDEN[name][2])
    if mode == "short":
        bad = raw[:-1]
    elif mode == "extra":
        bad = raw + b"\0"
    elif mode.startswith("size"):
        size = int.from_bytes(raw[:4], "little") + (1 if mode.endswith("plus") else -1)
        bad = changed(raw, 0, struct.pack("<I", size))
    elif mode == "magic":
        bad = changed(raw, 4, b"FAIL")
    elif mode == "version":
        bad = changed(raw, 8, b"\2\0")
    elif mode == "type":
        bad = changed(raw, 10, b"\xff\xff")
    elif mode == "nonce":
        bad = changed(raw, 20, b"\0" * 32)
    else:
        bad = changed(raw, 12, b"\0" * 8)
    with pytest.raises(p.ProtocolError):
        p.decode_message(bad)


@pytest.mark.parametrize("offset", [72, 73, 74, 75, 76, 101, 118, 127, 136])
def test_window_closed_enums_and_reserved(offset):
    with pytest.raises(p.ProtocolError):
        p.decode_message(changed(message().wire, 52+offset, b"\xff"))


@pytest.mark.parametrize("value", [math.inf, -math.inf, math.nan])
@pytest.mark.parametrize("offset", [119, 128, 137])
def test_nonfinite_metric_bits_refused(value, offset):
    with pytest.raises(p.ProtocolError):
        p.decode_message(changed(message().wire, 52+offset, struct.pack("<d", value)))


@pytest.mark.parametrize("value", [-0.0, 0.1, 6.0, 12.0, 18.0, float.fromhex("0x1.fffffffffffffp+1023")])
def test_finite_binary64_bits_preserved(value):
    metric = p.Metric(p.MetricState.FINITE, value)
    result = p.decode_message(wire(replace(window(), window_peak=metric))).body.window_peak
    assert struct.pack("<d", result.value_dbfs) == struct.pack("<d", value)


@pytest.mark.parametrize("state", list(p.MetricState)[1:])
def test_null_metric_reserved_zero_and_negative_zero_rejection(state):
    body = replace(window(), window_peak=p.Metric(state, None))
    raw = wire(body)
    assert p.decode_message(raw).body.window_peak.value_dbfs is None
    with pytest.raises(p.ProtocolError):
        p.decode_message(changed(raw, 52+119, struct.pack("<d", -0.0)))


@pytest.mark.parametrize("state", [p.CountState.COUNTER_OVERFLOW, p.CountState.UNAVAILABLE])
def test_unavailable_counts_are_null_not_measured_zero(state):
    body = replace(window(), window_counts=p.WindowCounts(state, None, None, None),
                   session_counts=p.SessionCounts(state, None, None))
    result = p.decode_message(wire(body)).body
    assert result.window_counts.finite is None
    assert result.session_counts.clips is None
    with pytest.raises(p.ProtocolError):
        p.decode_message(changed(wire(body), 52+77, struct.pack("<Q", 1)))


@pytest.mark.parametrize("count", [-1, True, 1.0, p.MAX_INTEGER+1])
def test_counts_require_bounded_exact_integer(count):
    body = replace(window(), window_counts=p.WindowCounts(p.CountState.VALID, count, 0, 0))
    with pytest.raises(p.ProtocolError):
        wire(body)


def test_clips_cannot_exceed_finite_count():
    body = replace(window(), window_counts=p.WindowCounts(p.CountState.VALID, 1, 0, 2))
    with pytest.raises(p.ProtocolError):
        wire(body)


@pytest.mark.parametrize("root", ["C:\\", "C:\\project", "c:\\Users\\example", "\\\\server\\share\\project",
                                "C:\\Users\\..\\project", "C:\\Users\\project\\", "C:\\Users\\project:ads",
                                "C:\\Users\\bad.", "C:\\Users\\bad\x00name", "C:/Users/example"])
def test_bootstrap_path_syntax_is_fail_closed_without_io(root):
    body = replace(message("BOOTSTRAP").body, project_root=root)
    with pytest.raises(p.ProtocolError):
        p.encode_message(body, nonce=bytes(range(32)), sequence=1)


def test_private_bootstrap_and_message_repr_do_not_disclose_path():
    body = message("BOOTSTRAP").body
    assert body.project_root not in repr(body)
    assert body.project_root not in repr(message("BOOTSTRAP"))


@pytest.mark.parametrize("name,offset", [("WINDOW", 52), ("BOOTSTRAP", 52),
                                       ("RESULT_READY", 52+124), ("INVALIDATE", 52+16)])
def test_mixed_endian_uuid_is_not_rfc_uuid4(name, offset):
    raw = bytes.fromhex(GOLDEN[name][2])
    little_guid = bytes.fromhex("00000000000000408000000000000006")
    with pytest.raises(p.ProtocolError):
        p.decode_message(changed(raw, offset, little_guid))


@pytest.mark.parametrize("offset", [52+268, 52+269, 52+270])
def test_projection_closed_codes(offset):
    with pytest.raises(p.ProtocolError):
        p.decode_message(changed(message("RESULT_PROJECTION").wire, offset, b"\xff"))


def test_projection_hash_length_and_utf8_refusal():
    raw = message("RESULT_PROJECTION").wire
    for offset in (52+272, 52+276, len(raw)-1):
        with pytest.raises(p.ProtocolError):
            p.decode_message(changed(raw, offset, bytes((raw[offset] ^ 1,))))


@pytest.mark.parametrize("proof", [b'\xef\xbb\xbf{}', b'{"a":"\x00"}'])
def test_rehashed_proof_with_bom_or_nul_is_not_admitted(proof):
    raw = bytearray(message("RESULT_PROJECTION").wire[:52+308])
    raw[52+272:52+276] = len(proof).to_bytes(4, "little")
    raw[52+276:52+308] = sha256(proof).digest()
    raw += proof
    raw[:4] = (len(raw)-4).to_bytes(4, "little")
    with pytest.raises(p.ProtocolError):
        p.decode_message(bytes(raw))


def test_native_v1_cannot_promote_unknown_loss():
    for loss in p.Loss:
        observed = p.native_v1_observation(replace(window(), loss=loss))
        assert observed.loss is p.Loss.UNKNOWN
        assert observed.capture_point is p.CapturePoint.CONTROLLER_FLOAT32_PRE_DRAW


def test_response_correlation_binds_exact_wire():
    original = message()
    correlation = p.response_correlation(original)
    assert correlation.source_sha256 == original.sha256
    with pytest.raises(p.ProtocolError):
        p.response_correlation(replace(original, sequence=4))


def test_ordered_receiver_rejects_replay_skip_wrong_nonce_and_direction():
    for bad in [message().wire, wire(window(), sequence=3),
                p.encode_message(window(), nonce=b"x"*32, sequence=2),
                message("RESULT_READY").wire]:
        receiver = p.OrderedReceiver(allowed=(p.MessageType.BOOTSTRAP, p.MessageType.WINDOW))
        receiver.accept(message("BOOTSTRAP").wire)
        if bad == message().wire:
            receiver.accept(bad)
        with pytest.raises(p.ProtocolError):
            receiver.accept(bad)
        assert receiver.closed
        with pytest.raises(p.ProtocolError):
            receiver.accept(message().wire)


def test_accumulator_fragmentation_and_coalescing():
    chunks = message("BOOTSTRAP").wire + message().wire
    reader = p.FrameAccumulator()
    results = []
    for i, value in enumerate(chunks):
        results.extend(reader.feed(bytes((value,)), now_ns=i))
    assert [x.kind for x in results] == [p.MessageType.BOOTSTRAP, p.MessageType.WINDOW]
    assert p.FrameAccumulator().feed(chunks, now_ns=0) == tuple(results)


def test_accumulator_huge_prefix_timeout_eof_no_resync():
    reader = p.FrameAccumulator()
    with pytest.raises(p.ProtocolError):
        reader.feed(struct.pack("<I", 65533), now_ns=0)
    with pytest.raises(p.ProtocolError):
        reader.feed(message().wire, now_ns=0)
    reader = p.FrameAccumulator()
    reader.feed(b"\xc1", now_ns=0)
    reader.expire(999_999_999)
    with pytest.raises(p.ProtocolError):
        reader.expire(1_000_000_000)
    reader = p.FrameAccumulator()
    reader.feed(b"\xc1", now_ns=0)
    reader.eof()
    with pytest.raises(p.ProtocolError):
        reader.feed(message().wire, now_ns=1)


@pytest.mark.parametrize("elapsed,accepted", [(249_000_000, True), (250_000_000, False), (251_000_000, False)])
def test_monotonic_249_250_251_display_boundary(elapsed, accepted):
    scheduler = p.LatestWindowScheduler()
    scheduler.offer(window(), now_ns=0)
    job = scheduler.take()
    assert scheduler.finish(job, message("RESULT_PROJECTION").body, now_ns=elapsed) is accepted
    assert (scheduler.display(now_ns=elapsed) is not None) is accepted
    assert scheduler.display(now_ns=250_000_000) is None


def test_latest_one_stale_clear_and_owned_active_slot():
    scheduler = p.LatestWindowScheduler()
    scheduler.offer(window(), now_ns=0)
    old = scheduler.take()
    for seq in range(2, 101):
        scheduler.offer(replace(window(), ui_sequence=seq), now_ns=seq)
        assert scheduler.occupancy == (1, 1)
        assert scheduler.take() is None
    with pytest.raises(p.ProtocolError):
        scheduler.finish(replace(old), None, now_ns=101)
    assert scheduler.occupancy == (1, 1)
    assert not scheduler.finish(old, message("RESULT_PROJECTION").body, now_ns=102)
    assert scheduler.display(now_ns=102) is None
    latest = scheduler.take()
    assert latest.window.ui_sequence == 100


@pytest.mark.parametrize("action", ["invalidate", "close", "new_window"])
def test_invalidation_keeps_lease_slot_until_exact_job_drains(action):
    scheduler = p.LatestWindowScheduler()
    scheduler.offer(window(), now_ns=0)
    job = scheduler.take()
    if action == "new_window":
        scheduler.offer(replace(window(), ui_sequence=2), now_ns=1)
    else:
        getattr(scheduler, action)()
    assert scheduler.occupancy[0] == 1
    assert scheduler.take() is None
    assert not scheduler.finish(job, message("RESULT_PROJECTION").body, now_ns=2)
    assert scheduler.occupancy[0] == 0
    assert scheduler.display(now_ns=2) is None


def test_scheduler_concurrent_offer_is_bounded_and_does_not_run_user_callbacks():
    scheduler = p.LatestWindowScheduler()
    scheduler.offer(window(), now_ns=0)
    active = scheduler.take()
    errors = []
    def producer():
        try:
            for seq in range(2, 1000):
                scheduler.offer(replace(window(), ui_sequence=seq), now_ns=seq)
        except Exception as error:
            errors.append(type(error))
    thread = threading.Thread(target=producer)
    thread.start()
    thread.join(2)
    assert not thread.is_alive() and not errors
    assert scheduler.occupancy == (1, 1)
    scheduler.finish(active, None, now_ns=1000)
    assert scheduler.take().window.ui_sequence == 999
